  "test": "import { describe, expect, it } from 'vitest';
import { priceCart, Promotion, CartLine } from '../src/pricing';

describe('regression pricing total negative', () => {
  it('el descuento total no puede exceder el subtotal permitiendo totales negativos', () => {
    const lines: CartLine[] = [
      { sku: 'ITEM-1', qty: 1, unitPriceCents: 1000, category: 'general' },
    ];
    const promotions: Promotion[] = [
      { type: 'COUPON_FIXED', code: 'GRANDE', amountCents: 1500, minPurchaseCents: 500 },
    ];

    const totals = priceCart(lines, promotions, 'GRANDE');
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });
});
"
